func (t *RefTermTerm) CompareTo(o any) int {
	ao := o.(Term)
	if ao == Term(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*RefTermTerm)
	if c := strings.Compare(t.L, tco.L); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

